"""Render both prompt documents from their canonical JSON; --check detects drift."""
import argparse
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent


def render_main(cases):
    lines = ['# Multi-turn prompts and grading — draft', '',
             'Generated by `render_docs.py` from canonical [cases.json](cases.json). Edit JSON, then regenerate. Send only each `prompt` to Nuru; grading, source paths, oracles and setup are evaluator-only. Turn order is fixed. Empty `checks` award no regex acceptance score; `mechanical_checks` supply separate deterministic screening evidence.', '']
    for key, case in cases.items():
        lines += [f"## {key}: {case['name']}", '',
                  f"**Lane:** {case['mode']}. **Setup:** {case['setup']}", '',
                  '**Evidence:** ' + ', '.join(f'`{p}`' for p in case['sources']) + '.', '']
        if case.get('coverage_note'):
            lines += ['**Coverage:** ' + case['coverage_note'], '']
        for turn in case['turns']:
            grade = turn['grading']
            lines += [f"### Turn {turn['turn']}", '', '> ' + turn['prompt'], '', '**Full-credit requirements:**', '']
            lines += ['- ' + r for r in grade['required']]
            if grade['reject']:
                lines += ['', '**Reject:** ' + ' '.join(grade['reject'])]
            lines += ['', '**Vault expectation:** ' + grade['expected_vault_state'], '']
            if turn.get('mechanical_checks'):
                lines += ['**Deterministic screens:** `' + json.dumps(turn['mechanical_checks'], ensure_ascii=False) + '`.', '']
        if case.get('numeric_oracle'):
            lines += ['**Evaluator-only numeric oracle:**', '', '```json', json.dumps(case['numeric_oracle'], indent=2, ensure_ascii=False), '```', '']
    return '\n'.join(lines)


def render_pairs(package):
    lines = ['# Historical failure pairs: prompts and grading (2026-10-07)', '',
             'Generated by `render_docs.py` from canonical [cases.json](cases.json). Draft specification, **NOT RUN**. These are fixed user-guided decompositions, not a demonstrated repair or autonomous planner. See [protocol](README.md) and [historical selection](historical-findings.md). The final multi-turn prompt is the exact original suite prompt; do not send grading information to Nuru.', '']
    for case in package['cases']:
        lines += [f"## {case['id']} — original test {case['original_test']}: {case['title']}", '',
                  f"Selection: **{case['selection']}**. {case['historical_evidence']}", '',
                  '### One-shot arm', '', '```text', case['one_shot_prompt'], '```', '', '### Multi-turn arm', '']
        for turn in case['multi_turn']:
            lines += [f"**Turn {turn['turn']}**", '', '```text', turn['prompt'], '```', '']
        lines += ['### Shared outcome grading — 5 points', '']
        lines += [f"- **{r['id']} (1 point):** {r['full_credit']}" for r in case['shared_rubric']]
        lines += ['', 'Critical rejections (fail the run regardless of points):', '']
        lines += ['- ' + r for r in case['critical_rejections']]
        lines += ['', 'Expected vault state: ' + case['expected_vault_state'], '', 'Evidence sources:', '']
        lines += ['- `' + p + '`' for p in case['source_paths']]
        if case['numeric_oracle']:
            lines += ['', 'Evaluator-only numeric oracle:', '', '```json', json.dumps(case['numeric_oracle'], indent=2, ensure_ascii=False), '```']
        lines += ['']
    lines += ['## Capability / feasibility diagnostics', '',
              'These do not belong in the supported-task improvement aggregate. Test 27 can be separately paired as a refusal control.', '']
    for case in package['capability_diagnostics']:
        lines += [f"### Original test {case['original_test']}", '', '**Original prompt:** ' + case['one_shot_prompt'], '',
                  '**Classification:** ' + case['classification'], '', case['reason'], '', '**Optional diagnostic sequence:**', '']
        lines += [f'{i + 1}. {prompt}' for i, prompt in enumerate(case['diagnostic_turns'])]
        lines += ['', '**Expected behavior:** ' + case['correct_behavior'], '', '**What would change feasibility:** ' + case['enablement'], '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    targets = [(HERE / 'prompts-and-grading.md', render_main(json.loads((HERE / 'cases.json').read_text()))),
               (HERE / 'failure_pairs/prompts-and-grading.md', render_pairs(json.loads((HERE / 'failure_pairs/cases.json').read_text())))]
    stale = []
    for path, text in targets:
        if args.check:
            if not path.exists() or path.read_text() != text:
                stale.append(str(path.relative_to(HERE)))
        else:
            path.write_text(text)
    if stale:
        parser.exit(1, 'Generated documents differ: ' + ', '.join(stale) + '\n')
    print('Both prompt documents match canonical JSON.' if args.check else 'Rendered both prompt documents.')


if __name__ == '__main__':
    main()
